<?php
require_once __DIR__."/../../middleware/admin.php";require_once __DIR__."/../../config/koneksi.php";
$query=mysqli_query($koneksi,"SELECT b.*,k.nama_kategori FROM tbl_buku b LEFT JOIN tbl_kategori k ON b.id_kategori=k.id_kategori ORDER BY b.id_buku DESC");$total=mysqli_num_rows($query);
?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Kelola Buku</title><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.7.2/css/all.min.css"><link rel="stylesheet" href="<?= BASE_URL ?>/css/app.css"><link rel="stylesheet" href="<?= BASE_URL ?>/css/admin-buku.css"></head><body><?php render_flash();include __DIR__."/../partials/sidebar.php";?><main class="main book-admin"><header class="book-admin__top"><div><h1>Koleksi Buku</h1><p>Kelola informasi dan file buku digital perpustakaan.</p></div><a class="book-admin__button" href="tambah.php"><i class="fa-solid fa-plus"></i> Tambah Buku</a></header><div class="book-admin__toolbar"><div class="book-admin__search"><i class="fa-solid fa-magnifying-glass"></i><input id="book-search" type="search" placeholder="Cari judul, penulis, atau kategori..."></div><span><?= $total ?> buku</span></div><section class="book-admin__panel"><div class="book-admin__table-wrap"><table class="book-admin__table"><thead><tr><th>Cover</th><th>Informasi</th><th>Kategori</th><th>File digital</th><th>Aksi</th></tr></thead><tbody id="book-list"><?php if($total===0):?><tr><td class="book-admin__empty" colspan="5">Belum ada buku. Tambahkan koleksi pertamamu.</td></tr><?php endif;?><?php while($b=mysqli_fetch_assoc($query)):?><tr data-search="<?= e(strtolower($b['judul_buku'].' '.$b['penulis_buku'].' '.($b['nama_kategori']??''))) ?>"><td><?php if(!empty($b['cover_buku'])):?><img class="book-admin__cover" src="<?= BASE_URL ?>/uploads/cover/<?= e($b['cover_buku']) ?>" alt=""><?php else:?><span class="book-admin__cover-empty"><i class="fa-solid fa-book"></i></span><?php endif;?></td><td><span class="book-admin__title"><?= e($b['judul_buku']) ?></span><span class="book-admin__sub"><?= e($b['penulis_buku']) ?> · <?= e($b['tahun_terbit']?:'-') ?></span></td><td><span class="book-admin__badge"><?= e($b['nama_kategori']??'Tanpa kategori') ?></span></td><td><span class="book-admin__status <?= empty($b['pdf_buku'])?'book-admin__status--empty':'' ?>"><?= empty($b['pdf_buku'])?'Belum ada PDF':'PDF tersedia' ?></span></td><td><div class="book-admin__actions"><a class="book-admin__action" title="Detail" href="detail.php?id=<?= (int)$b['id_buku'] ?>"><i class="fa-regular fa-eye"></i></a><a class="book-admin__action" title="Edit" href="edit.php?id=<?= (int)$b['id_buku'] ?>"><i class="fa-regular fa-pen-to-square"></i></a><a class="book-admin__action book-admin__action--danger" title="Hapus" href="hapus.php?id=<?= (int)$b['id_buku'] ?>" onclick="return confirm('Yakin ingin menghapus buku ini?')"><i class="fa-regular fa-trash-can"></i></a></div></td></tr><?php endwhile;?></tbody></table></div></section></main><script>const search=document.getElementById('book-search');search.addEventListener('input',()=>{const q=search.value.toLowerCase().trim();document.querySelectorAll('#book-list tr[data-search]').forEach(row=>row.hidden=!row.dataset.search.includes(q));});</script></body></html>
